import { BreakpointObserver, BreakpointState } from '@angular/cdk/layout';
import { NgIf, NgTemplateOutlet } from '@angular/common';
import {
  booleanAttribute,
  ChangeDetectionStrategy,
  Component,
  EventEmitter,
  HostBinding,
  inject,
  Input,
  numberAttribute,
  OnChanges,
  OnInit,
  Output,
  SimpleChanges,
  TemplateRef,
  ViewEncapsulation,
} from '@angular/core';
import { TranslocoModule } from '@jsverse/transloco';
import { QDestroyService } from '@questrade/allspark-angular-components/core/services';
import { QIconComponent, QIconRegistryService } from '@questrade/allspark-angular-components/icon';
import {
  ALLSPARK_SCOPE,
  MISSING_KEY_HANDLER,
} from '@questrade/allspark-angular-components/transloco';
import { clear } from '@questrade/allspark-icons/icons';
import { filter, takeUntil } from 'rxjs';
import { QBannerDensity } from './types/banner-density.type';
import { QBannerHierarchy } from './types/banner-hierarchy.type';
import { QBannerStackButtonsMode } from './types/banner-stack-buttons-mode.type';
import { QBannerVariant } from './types/banner-variant.type';

@Component({
  selector: 'q-banner',
  imports: [NgIf, NgTemplateOutlet, QIconComponent, TranslocoModule],
  providers: [MISSING_KEY_HANDLER, ALLSPARK_SCOPE, QDestroyService],
  templateUrl: './banner.component.html',
  styleUrl: './banner.component.scss',
  encapsulation: ViewEncapsulation.None,
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class QBannerComponent implements OnInit, OnChanges {
  @Output() readonly closeIconClick = new EventEmitter<Event>();

  @Input() title = '';
  @Input() icon = '';
  @Input() variant: QBannerVariant = 'auxiliary';
  @Input() density: QBannerDensity = 'default';
  @Input() hierarchy: QBannerHierarchy = 'low';
  @Input() titleTemplate: TemplateRef<unknown> | null = null;
  @Input() stackButtonsMode: QBannerStackButtonsMode = 'auto';
  @Input({ transform: numberAttribute }) stackButtonsBreakpoint = 599;
  @Input({ transform: booleanAttribute }) rounded = false;
  @Input({ transform: booleanAttribute }) showCloseIcon = false;
  @Input() @HostBinding('attr.data-qt') dataQt = 'q-banner';

  @HostBinding('attr.role') _hostRole = 'alert';
  @HostBinding('attr.title') _hostTitle = '';

  @HostBinding('class') get hostClasses(): string {
    return [
      'q-banner',
      `q-banner-${this.variant}`,
      this.density === 'compact' && 'q-banner-compact',
      this.rounded && 'q-banner-rounded',
      this.showCloseIcon && 'q-banner-closeable',
      (this.stackButtonsMode === 'always' || this._bannerButtonsStacked) &&
        'q-banner-buttons-stacked',
      `q-banner-hierarchy-${this.hierarchy}`,
    ]
      .filter(Boolean)
      .join(' ');
  }

  private _bannerButtonsStacked = false;
  private readonly _iconRegistry = inject(QIconRegistryService);
  private readonly _destroy$ = inject(QDestroyService);
  private readonly _breakpointObserver = inject(BreakpointObserver);

  ngOnInit(): void {
    this._iconRegistry.registerIcons([clear]);

    this._breakpointObserver
      .observe([`(max-width: ${this.stackButtonsBreakpoint}px)`])
      .pipe(
        filter(() => this.stackButtonsMode === 'auto'),
        takeUntil(this._destroy$),
      )
      .subscribe((result: BreakpointState) => {
        this._bannerButtonsStacked = result.matches;
      });
  }

  ngOnChanges(changes: SimpleChanges): void {
    const { stackButtonsMode, stackButtonsBreakpoint } = changes;
    if (stackButtonsMode || stackButtonsBreakpoint) {
      this._bannerButtonsStacked =
        this._breakpointObserver.isMatched([`(max-width: ${this.stackButtonsBreakpoint}px)`]) &&
        this.stackButtonsMode === 'auto';
    }
  }

  _onCloseIconClick(event: Event): void {
    this.closeIconClick.emit(event);
  }

  get _titleVisible(): boolean {
    return this.density === 'default' && !!(this.title || this.titleTemplate);
  }
}
